33	// handleUpsert stores a registration or an update for one service instance.
34	// Repeating the same (service name, instance id) pair overwrites the record.
35	func (s *Server) handleUpsert(c *gin.Context) {
36		bag, apiErr := buildParamBag(c)
37		if apiErr != nil {
38			writeError(c, apiErr)
39			return
40		}
41	
42		serviceName, apiErr := bag.requiredText(serviceNameKeys, "service_name must not be empty")
43		if apiErr != nil {
44			writeError(c, apiErr)
45			return
46		}
47		instanceID, apiErr := bag.requiredText(instanceIDKeys, "instance_id must not be empty")
48		if apiErr != nil {
49			writeError(c, apiErr)
50			return
51		}
52		weightValue, ok := bag.get(weightKeys)
53		if !ok {
54			writeError(c, errInvalidParameter("weight must be a positive number"))
55			return
56		}
57		weight, ok := positiveNumber(weightValue)
58		if !ok {
59			writeError(c, errInvalidParameter("weight must be a positive number"))
60			return
61		}
62		port := int64(0)
63		if portValue, present := bag.get(portKeys); present {
64			port, ok = parsePortValue(portValue)
65			if !ok {
66				writeError(c, errInvalidParameter("port must be a non-negative integer"))
67				return
68			}
69		}
70		heartbeatValue, ok := bag.get(heartbeatKeys)
71		if !ok {
72			writeError(c, errInvalidParameter("heartbeat_at is required"))
73			return
74		}
75		heartbeatAt, ok := parseTimeValue(heartbeatValue)
76		if !ok {
77			writeError(c, errInvalidParameter("heartbeat_at must be a valid timestamp"))
78			return
79		}
80	
81		healthy := false
82		if healthValue, ok := bag.get(healthKeys); ok {
83			healthy, ok = strictBoolValue(healthValue)
84			if !ok {
85				writeError(c, errInvalidParameter("healthy must be a boolean true or false"))
86				return
87			}
88		}
89		address := ""
90		if addressValue, ok := bag.get(addressKeys); ok {
91			address = stringValue(addressValue)
92		}
93	
94		// evaluate_at is optional on registrations. The clock-skew guard rejects a
95		// heartbeat later than the caller's evaluation point.
96		if evaluateValue, ok := bag.get(evaluateAtKeys); ok {
97			evaluateAt, parsed := parseTimeValue(evaluateValue)
98			if !parsed {
99				writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
100				return
101			}
102			if evaluateAt.Before(heartbeatAt) {
103				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
104				return
105			}
106		}
107	
108		input := store.InstanceInput{
109			ServiceName: serviceName,
110			InstanceID:  instanceID,
111			Address:     address,
112			Port:        port,
113			Healthy:     healthy,
114			Weight:      weight,
115			HeartbeatAt: heartbeatAt,
116		}
117		instance, err := s.store.UpsertInstance(input)
118		if err != nil {
119			writeError(c, errStorageUnavailable())
120			return
121		}
122		c.JSON(200, gin.H{"instance": instanceJSON(instance)})
123	}
