149			if apiErr != nil {
150				writeError(c, apiErr)
151				return
152			}
153		} else if serviceName == "" {
154			writeError(c, errInvalidParameter("service_name must not be empty"))
155			return
156		}
157	
158		rawEntries, ok := bag.get([]string{"instances"})
159		if !ok {
160			writeError(c, errInvalidParameter("instances must be a non-empty list"))
161			return
162		}
163		entries, ok := rawEntries.([]any)
164		if !ok || len(entries) == 0 {
165			writeError(c, errInvalidParameter("instances must be a non-empty list"))
166			return
167		}
168	
169		inputs := make([]store.InstanceInput, 0, len(entries))
170		seen := make(map[string]struct{}, len(entries))
171		for _, rawEntry := range entries {
172			entry, ok := rawEntry.(map[string]any)
173			if !ok {
174				writeError(c, errInvalidParameter("each instance must be an object"))
175				return
176			}
177			instanceID := strings.TrimSpace(stringValue(entry["instance_id"]))
178			if instanceID == "" {
179				writeError(c, errInvalidParameter("instance_id must not be empty"))
180				return
181			}
182			if _, duplicated := seen[instanceID]; duplicated {
183				writeError(c, errInvalidParameter("instance_id must not be duplicated"))
184				return
185			}
186			weightValue, present := entry["weight"]
187			if !present {
188				writeError(c, errInvalidParameter("weight must be a positive number"))
189				return
190			}
191			weight, ok := positiveNumber(weightValue)
192			if !ok {
193				writeError(c, errInvalidParameter("weight must be a positive number"))
194				return
195			}
196			port := int64(0)
197			if portValue, present := entry["port"]; present {
198				port, ok = parsePortValue(portValue)
199				if !ok {
200					writeError(c, errInvalidParameter("port must be a non-negative integer"))
201					return
202				}
203			}
204			healthy := false
205			if healthValue, present := entry["healthy"]; present {
206				healthy, ok = strictBoolValue(healthValue)
207				if !ok {
208					writeError(c, errInvalidParameter("healthy must be a boolean true or false"))
209					return
210				}
211			}
212			heartbeatValue, present := entry["heartbeat_at"]
213			if !present {
214				writeError(c, errInvalidParameter("heartbeat_at is required"))
215				return
216			}
217			heartbeatAt, parsed := parseTimeValue(heartbeatValue)
218			if !parsed {
219				writeError(c, errInvalidParameter("heartbeat_at must be a valid timestamp"))
220				return
221			}
222			address := ""
223			if addressValue, present := entry["address"]; present {
224				address = stringValue(addressValue)
225			}
226			seen[instanceID] = struct{}{}
227			inputs = append(inputs, store.InstanceInput{
228				ServiceName: serviceName,
229				InstanceID:  instanceID,
230				Address:     address,
231				Port:        port,
232				Healthy:     healthy,
233				Weight:      weight,
234				HeartbeatAt: heartbeatAt,
235			})
236		}
237	
238		instances, err := s.store.UpsertInstances(inputs)
239		if err != nil {
240			writeError(c, errStorageUnavailable())
241			return
242		}
243		results := make([]gin.H, 0, len(instances))
244		for _, instance := range instances {
245			results = append(results, instanceJSON(instance))
246		}
247		c.JSON(200, gin.H{
248			"service_name": serviceName,
249			"registered":   len(results),
250			"instances":    results,
251		})
252	}
