679		instance, apiErr := s.loadInstance(c)
680		if apiErr != nil {
681			writeError(c, apiErr)
682			return
683		}
684		c.JSON(200, gin.H{
685			"service_name": instance.ServiceName,
686			"instance_id":  instance.InstanceID,
687			"weight":       jsonWeight(instance.Weight),
688		})
689	}
690	
691	func (s *Server) handleGetHeartbeat(c *gin.Context) {
692		instance, apiErr := s.loadInstance(c)
693		if apiErr != nil {
694			writeError(c, apiErr)
695			return
696		}
697		c.JSON(200, gin.H{
698			"service_name": instance.ServiceName,
699			"instance_id":  instance.InstanceID,
700			"heartbeat_at": instance.HeartbeatAt.Format(time.RFC3339Nano),
701		})
702	}
703	
704	// handleListInstances returns all records of a service, never removing any.
705	func (s *Server) handleListInstances(c *gin.Context) {
706		bag, apiErr := buildParamBag(c)
707		if apiErr != nil {
708			writeError(c, apiErr)
709			return
710		}
711		serviceName, apiErr := bag.requiredText(serviceNameKeys, "service_name must not be empty")
712		if apiErr != nil {
713			writeError(c, apiErr)
714			return
715		}
716		instances, err := s.store.ListInstances(serviceName)
717		if err != nil {
718			writeError(c, errStorageUnavailable())
719			return
720		}
721		wantHealthy, hasFilter := false, false
722		if healthFilter, present := bag.get(healthKeys); present {
723			parsed, ok := parseHealthValue(healthFilter)
724			if !ok {
725				writeError(c, errInvalidParameter("healthy must be a boolean health state"))
726				return
727			}
728			wantHealthy, hasFilter = parsed, true
729		}
730		results := make([]gin.H, 0, len(instances))
731		for _, instance := range instances {
732			if hasFilter && instance.Healthy != wantHealthy {
733				continue
734			}
735			results = append(results, instanceJSON(instance))
736		}
737		sortInstances(results)
738		c.JSON(200, gin.H{"service_name": serviceName, "instances": results})
739	}
740	
741	// handleListServices serves the read-only service overview. It aggregates the
742	// current SQLite records of every service at the requested evaluation point
743	// without creating, updating or deleting anything, and in particular without
744	// running the discovery lost-record cleanup. Lost instances stay stored and
745	// are only counted as lost.
746	func (s *Server) handleListServices(c *gin.Context) {
747		bag, apiErr := buildParamBag(c)
748		if apiErr != nil {
749			writeError(c, apiErr)
750			return
751		}
752		evaluateValue, ok := bag.get(evaluateAtKeys)
753		if !ok {
754			writeError(c, errInvalidParameter("evaluate_at is required"))
755			return
756		}
757		evaluateAt, ok := parseTimeValue(evaluateValue)
758		if !ok {
759			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
760			return
761		}
762		timeoutValue, ok := bag.get(timeoutKeys)
763		if !ok {
764			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
765			return
766		}
767		timeout, ok := parseTimeout(timeoutValue)
768		if !ok || timeout <= 0 {
769			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
770			return
771		}
772	
773		instances, err := s.store.ListAllInstances()
774		if err != nil {
775			writeError(c, errStorageUnavailable())
776			return
777		}
778		for _, instance := range instances {
779			if evaluateAt.Before(instance.HeartbeatAt) {
780				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
781				return
782			}
783		}
784	
785		// Aggregate records per service. The same counters classify every
786		// record exactly once, so total_instances is always the sum of the
787		// three state counters.
788		byService := make(map[string]*serviceCounters)
789		for _, instance := range instances {
790			counters := byService[instance.ServiceName]
791			if counters == nil {
792				counters = &serviceCounters{}
793				byService[instance.ServiceName] = counters
794			}
795			counters.total++
796			switch {
797			case evaluateAt.After(instance.HeartbeatAt.Add(timeout)):
798				counters.lost++
799			case instance.Healthy:
800				counters.available++
801			default:
802				counters.unhealthyFresh++
803			}
804		}
805	
806		serviceNames := make([]string, 0, len(byService))
807		for serviceName := range byService {
808			serviceNames = append(serviceNames, serviceName)
809		}
810		sort.Strings(serviceNames)
811	
812		services := make([]gin.H, 0, len(serviceNames))
813		for _, serviceName := range serviceNames {
814			counters := byService[serviceName]
815			services = append(services, gin.H{
816				"service_name":              serviceName,
817				"total_instances":           counters.total,
818				"available_instances":       counters.available,
819				"unhealthy_fresh_instances": counters.unhealthyFresh,
820				"lost_instances":            counters.lost,
821			})
822		}
823		c.JSON(200, gin.H{"services": services})
824	}
825	
826	type serviceCounters struct {
827		total          int
828		available      int
829		unhealthyFresh int
830		lost           int
831	}
832	
833	// handleDiscover implements the weighted discovery entry: only explicitly
834	// healthy instances whose last heartbeat is not strictly past the lost
835	// boundary are returned. An instance exactly on the boundary is still
836	// online. Records strictly past the boundary are removed by the lost
837	// cleanup in a single transaction, so a storage failure leaves every
838	// record unchanged and yields no candidate list; online and
839	// unhealthy-but-fresh records are never touched.
840	func (s *Server) handleDiscover(c *gin.Context) {
841		bag, apiErr := buildParamBag(c)
842		if apiErr != nil {
843			writeError(c, apiErr)
844			return
845		}
846		serviceName, apiErr := bag.requiredText(serviceNameKeys, "service_name must not be empty")
847		if apiErr != nil {
848			writeError(c, apiErr)
849			return
850		}
851		evaluateValue, ok := bag.get(evaluateAtKeys)
852		if !ok {
853			writeError(c, errInvalidParameter("evaluate_at is required"))
854			return
855		}
856		evaluateAt, ok := parseTimeValue(evaluateValue)
857		if !ok {
858			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
859			return
860		}
861		timeoutValue, ok := bag.get(timeoutKeys)
862		if !ok {
863			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
864			return
865		}
866		timeout, ok := parseTimeout(timeoutValue)
867		if !ok || timeout <= 0 {
868			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
869			return
870		}
871	
872		instances, err := s.store.ListInstances(serviceName)
873		if err != nil {
874			writeError(c, errStorageUnavailable())
875			return
876		}
877		for _, instance := range instances {
878			if evaluateAt.Before(instance.HeartbeatAt) {
879				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
880				return
881			}
882		}
883		candidates := make([]gin.H, 0, len(instances))
884		lostKeys := make([]store.InstanceKey, 0)
885		for _, instance := range instances {
886			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
887				lostKeys = append(lostKeys, store.InstanceKey{
888					ServiceName: instance.ServiceName,
889					InstanceID:  instance.InstanceID,
890				})
891				continue
892			}
893			if !instance.Healthy {
894				continue
895			}
896			candidates = append(candidates, instanceJSON(instance))
897		}
898		// Lost cleanup deletes records strictly past the timeout. It runs only
899		// after the request is fully validated, and all lost records are removed
900		// in one transaction: a storage failure rolls everything back, so a
901		// failed request never leaves partial deletions behind.
902		if len(lostKeys) > 0 {
903			if err := s.store.DeleteInstances(lostKeys); err != nil {
904				writeError(c, errStorageUnavailable())
905				return
906			}
907		}
908		sortDiscoverHits(candidates)
909		c.JSON(200, gin.H{
910			"service_name":      serviceName,
911			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
912			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
913			"instances":         candidates,
914		})
915	}
916	
917	// handleBatchDiscover implements POST /api/v1/discover/batch. Several
918	// services share one evaluation point and timeout. Parameters and stored
919	// data are fully validated before any record is removed: every specified
920	// service is read first, the clock-skew guard covers every instance of
921	// every specified service, and lost records across all services are removed
922	// in one transaction so a failure never leaves partial deletions. Services
923	// that are not requested are never read or touched; a requested service
924	// without records yields an empty instance list while keeping its place in
925	// the request order.
926	func (s *Server) handleBatchDiscover(c *gin.Context) {
927		body, apiErr := readJSONObject(c)
928		if apiErr != nil {
929			writeError(c, apiErr)
930			return
931		}
932	
933		rawNames, present := body["service_names"]
934		if !present {
935			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
936			return
937		}
938		entries, ok := rawNames.([]any)
939		if !ok || len(entries) == 0 {
940			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
941			return
942		}
943		serviceNames := make([]string, 0, len(entries))
944		seen := make(map[string]struct{}, len(entries))
945		for _, rawName := range entries {
946			name, ok := rawName.(string)
947			if !ok {
948				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
949				return
950			}
951			name = strings.TrimSpace(name)
952			if name == "" {
953				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
954				return
955			}
956			if _, duplicated := seen[name]; duplicated {
957				writeError(c, errInvalidParameter("service_names must not contain duplicates"))
958				return
959			}
960			seen[name] = struct{}{}
961			serviceNames = append(serviceNames, name)
962		}
963	
964		evaluateValue, present := body["evaluate_at"]
965		if !present {
966			writeError(c, errInvalidParameter("evaluate_at is required"))
967			return
968		}
969		evaluateAt, ok := parseTimeValue(evaluateValue)
970		if !ok {
971			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
972			return
973		}
974		timeoutValue, present := body["heartbeat_timeout"]
975		if !present {
976			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
977			return
978		}
979		timeout, ok := parseTimeout(timeoutValue)
980		if !ok || timeout <= 0 {
981			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
982			return
983		}
984	
985		// Read every requested service before any classification or deletion,
986		// so a storage read failure changes nothing.
987		byService := make(map[string][]store.Instance, len(serviceNames))
988		for _, serviceName := range serviceNames {
989			instances, err := s.store.ListInstances(serviceName)
990			if err != nil {
991				writeError(c, errStorageUnavailable())
992				return
993			}
994			byService[serviceName] = instances
995		}
996		// The clock-skew guard covers all records before the lost boundary is
997		// applied, rejecting the whole batch without deleting anything.
998		for _, serviceName := range serviceNames {
999			for _, instance := range byService[serviceName] {
1000				if evaluateAt.Before(instance.HeartbeatAt) {
1001					writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1002					return
1003				}
1004			}
1005		}
1006	
1007		lostKeys := make([]store.InstanceKey, 0)
1008		for _, serviceName := range serviceNames {
1009			for _, instance := range byService[serviceName] {
1010				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1011					lostKeys = append(lostKeys, store.InstanceKey{
1012						ServiceName: instance.ServiceName,
1013						InstanceID:  instance.InstanceID,
1014					})
1015				}
1016			}
1017		}
1018		// All lost records are removed atomically across services.
1019		if len(lostKeys) > 0 {
1020			if err := s.store.DeleteInstances(lostKeys); err != nil {
1021				writeError(c, errStorageUnavailable())
1022				return
1023			}
1024		}
1025	
1026		services := make([]gin.H, 0, len(serviceNames))
1027		for _, serviceName := range serviceNames {
1028			candidates := make([]gin.H, 0)
1029			for _, instance := range byService[serviceName] {
1030				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1031					continue
1032				}
1033				if !instance.Healthy {
1034					continue
1035				}
1036				candidates = append(candidates, instanceJSON(instance))
1037			}
1038			sortDiscoverHits(candidates)
1039			services = append(services, gin.H{
1040				"service_name": serviceName,
1041				"instances":    candidates,
1042			})
1043		}
1044		c.JSON(200, gin.H{
1045			"services":          services,
1046			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1047			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1048		})
1049	}
1050	
1051	// handleCleanup implements the standalone lost-instance cleanup entry. An
1052	// omitted service_name evaluates every service; an explicit service_name
1053	// must be non-empty and scopes the cleanup to that one service, leaving
1054	// every other service untouched. Only records strictly past the lost
1055	// boundary are deleted: records exactly on the boundary, still-online
1056	// records and unhealthy-but-fresh records are all kept. Every parameter is
1057	// validated before any deletion, and the deletion itself runs in one
1058	// transaction so a storage failure leaves no partial result.
1059	func (s *Server) handleCleanup(c *gin.Context) {
1060		bag, apiErr := buildParamBag(c)
1061		if apiErr != nil {
1062			writeError(c, apiErr)
1063			return
1064		}
1065	
1066		serviceName := ""
1067		scoped := false
1068		if value, present := bag.get(serviceNameKeys); present {
1069			serviceName = strings.TrimSpace(stringValue(value))
1070			if serviceName == "" {
1071				writeError(c, errInvalidParameter("service_name must not be empty"))
1072				return
1073			}
1074			scoped = true
1075		}
1076		evaluateValue, ok := bag.get(evaluateAtKeys)
1077		if !ok {
1078			writeError(c, errInvalidParameter("evaluate_at is required"))
1079			return
1080		}
1081		evaluateAt, ok := parseTimeValue(evaluateValue)
1082		if !ok {
1083			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
1084			return
1085		}
1086		timeoutValue, ok := bag.get(timeoutKeys)
1087		if !ok {
1088			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1089			return
1090		}
1091		timeout, ok := parseTimeout(timeoutValue)
1092		if !ok || timeout <= 0 {
1093			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1094			return
1095		}
1096	
1097		var instances []store.Instance
1098		var err error
1099		if scoped {
1100			instances, err = s.store.ListInstances(serviceName)
1101		} else {
1102			instances, err = s.store.ListAllInstances()
1103		}
1104		if err != nil {
1105			writeError(c, errStorageUnavailable())
1106			return
1107		}
1108		for _, instance := range instances {
1109			if evaluateAt.Before(instance.HeartbeatAt) {
1110				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1111				return
1112			}
1113		}
1114	
1115		lost := make([]store.Instance, 0)
1116		keys := make([]store.InstanceKey, 0)
1117		for _, instance := range instances {
1118			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1119				lost = append(lost, instance)
1120				keys = append(keys, store.InstanceKey{
1121					ServiceName: instance.ServiceName,
1122					InstanceID:  instance.InstanceID,
1123				})
1124			}
1125		}
1126		if len(keys) > 0 {
1127			if err := s.store.DeleteInstances(keys); err != nil {
1128				writeError(c, errStorageUnavailable())
1129				return
1130			}
1131		}
1132	
1133		sort.SliceStable(lost, func(i, j int) bool {
1134			if lost[i].ServiceName != lost[j].ServiceName {
1135				return lost[i].ServiceName < lost[j].ServiceName
1136			}
1137			return lost[i].InstanceID < lost[j].InstanceID
1138		})
1139		removed := make([]gin.H, 0, len(lost))
1140		for _, instance := range lost {
1141			removed = append(removed, instanceJSON(instance))
1142		}
1143		c.JSON(200, gin.H{
1144			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1145			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1146			"removed":           len(removed),
1147			"instances":         removed,
1148		})
1149	}
1150	
1151	// sortDiscoverHits orders discovery hits by weight descending, then instance
1152	// id ascending, giving deterministic output for identical input.
1153	func sortDiscoverHits(instances []gin.H) {
1154		sort.SliceStable(instances, func(i, j int) bool {
1155			leftWeight, _ := toFloat(instances[i]["weight"])
1156			rightWeight, _ := toFloat(instances[j]["weight"])
1157			if leftWeight != rightWeight {
1158				return leftWeight > rightWeight
1159			}
1160			return stringValue(instances[i]["instance_id"]) < stringValue(instances[j]["instance_id"])
1161		})
1162	}
1163	
1164	// sortInstances orders by weight descending, heartbeat newest first, then
1165	// instance id ascending, giving deterministic output for identical input.
1166	func sortInstances(instances []gin.H) {
1167		sort.SliceStable(instances, func(i, j int) bool {
1168			left, right := instances[i], instances[j]
1169			leftWeight, _ := toFloat(left["weight"])
1170			rightWeight, _ := toFloat(right["weight"])
1171			if leftWeight != rightWeight {
1172				return leftWeight > rightWeight
1173			}
1174			leftHeartbeat, _ := parseTimeValue(left["heartbeat_at"])
1175			rightHeartbeat, _ := parseTimeValue(right["heartbeat_at"])
1176			if !leftHeartbeat.Equal(rightHeartbeat) {
1177				return leftHeartbeat.After(rightHeartbeat)
1178			}
1179			return stringValue(left["instance_id"]) < stringValue(right["instance_id"])
1180		})
1181	}
